CREATE TABLE IF NOT EXISTS companies (id text PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS memberships (company_id text REFERENCES companies(id), user_id text NOT NULL, role text NOT NULL CHECK(role IN ('admin','technician')), PRIMARY KEY(company_id,user_id));
CREATE TABLE IF NOT EXISTS clients (id text PRIMARY KEY, company_id text NOT NULL REFERENCES companies(id), data jsonb NOT NULL, archived boolean NOT NULL DEFAULT false, whatsapp_consent boolean NOT NULL DEFAULT false, UNIQUE(company_id,id));
CREATE TABLE IF NOT EXISTS plans (id text PRIMARY KEY, company_id text NOT NULL REFERENCES companies(id), day date NOT NULL, name text NOT NULL, technician_id text NOT NULL, capacity integer NOT NULL CHECK(capacity BETWEEN 1 AND 30), minutes integer NOT NULL DEFAULT 480 CHECK(minutes BETWEEN 30 AND 1440), origin jsonb NOT NULL, destination jsonb NOT NULL, FOREIGN KEY(company_id,technician_id) REFERENCES memberships(company_id,user_id), UNIQUE(company_id,id));
CREATE TABLE IF NOT EXISTS visits (id text PRIMARY KEY, company_id text NOT NULL REFERENCES companies(id), client_id text NOT NULL, due_date date NOT NULL, status text NOT NULL DEFAULT 'pool' CHECK(status IN ('pool','planned','proposed','confirmed','completed','cancelled')), plan_id text, duration integer NOT NULL DEFAULT 60 CHECK(duration BETWEEN 5 AND 480), availability jsonb NOT NULL DEFAULT '{}', reason text NOT NULL DEFAULT '', version integer NOT NULL DEFAULT 1, work text, FOREIGN KEY(company_id,client_id) REFERENCES clients(company_id,id), FOREIGN KEY(company_id,plan_id) REFERENCES plans(company_id,id), UNIQUE(company_id,client_id,due_date), UNIQUE(company_id,id), CHECK ((status IN ('pool','cancelled') AND plan_id IS NULL) OR (status IN ('planned','proposed','confirmed','completed') AND plan_id IS NOT NULL)));
CREATE TABLE IF NOT EXISTS events (id bigserial PRIMARY KEY, company_id text NOT NULL, visit_id text, actor text NOT NULL, action text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS invitations (token_hash text PRIMARY KEY, company_id text NOT NULL REFERENCES companies(id), email text NOT NULL, role text NOT NULL CHECK(role IN ('admin','technician')), expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE IF NOT EXISTS outbox (id text PRIMARY KEY, company_id text NOT NULL, visit_id text NOT NULL, version integer NOT NULL, kind text NOT NULL CHECK(kind IN ('appointment','reminder')), state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','sending','sent','failed','obsolete','uncertain')), attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), claimed_at timestamptz, provider_id text, error text, UNIQUE(visit_id,version,kind), FOREIGN KEY(company_id,visit_id) REFERENCES visits(company_id,id));
CREATE TABLE IF NOT EXISTS webhook_receipts (id text PRIMARY KEY, received_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS visits_company_status ON visits(company_id,status);
CREATE INDEX IF NOT EXISTS outbox_pending ON outbox(state,available_at);
CREATE UNIQUE INDEX IF NOT EXISTS plans_technician_day ON plans(company_id,technician_id,day);

CREATE TABLE IF NOT EXISTS weekly_settings (company_id text PRIMARY KEY REFERENCES companies(id), config jsonb NOT NULL, updated_by text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS weekly_runs (id text PRIMARY KEY, company_id text NOT NULL REFERENCES companies(id), week_start date NOT NULL, week_end date NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','approved')), revision integer NOT NULL DEFAULT 1 CHECK(revision>0), payload jsonb NOT NULL, config jsonb NOT NULL, created_by text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), last_auto_week date, approved_at timestamptz, approved_by text, UNIQUE(company_id,week_start), CHECK(week_end=week_start+6), CHECK(extract(isodow FROM week_start)=1));
